1	<?php
2	
3	namespace App\Services;
4	
5	use App\Models\User;
6	use Illuminate\Support\Collection;
7	
8	/**
9	 * Single entry point for "what is this user's plan allowed to do", sourced from
10	 * the plan_feature matrix (admin-managed) — no hardcoded plan names anywhere.
11	 *
12	 * Feature slugs come from the features catalog, e.g. 'pin_search' (limit),
13	 * 'qr_code' / 'api_access' (boolean).
14	 */
15	class PlanEntitlements
16	{
17	    /** Per-request cache of a user's plan features, keyed by feature slug. */
18	    private array $cache = [];
19	
20	    private function features(User $user): Collection
21	    {
22	        return $this->cache[$user->id] ??= $user->plan
23	            ? $user->plan->comparisonFeatures()->get()->keyBy('slug')
24	            : collect();
25	    }
26	
27	    /**
28	     * Is the user's subscription currently usable? Trial and active count;
29	     * expired/cancelled/not_subscribed do not — those gate off search/chat
30	     * until the user pays.
31	     */
32	    public function subscriptionActive(User $user): bool
33	    {
34	        return in_array($user->subscription_status, ['trial', 'active'], true);
35	    }
36	
37	    /** Is a boolean feature included in the user's plan? */
38	    public function has(User $user, string $slug): bool
39	    {
40	        $feature = $this->features($user)->get($slug);
41	
42	        return $feature ? (bool) $feature->pivot->included : false;
43	    }
44	
45	    /** Raw matrix value for a feature ("3", "Unlimited", null). */
46	    public function value(User $user, string $slug): ?string
47	    {
48	        return $this->features($user)->get($slug)?->pivot->value;
49	    }
50	
51	    /**
52	     * Numeric monthly allowance for a limit feature:
53	     *   - integer   → that many (e.g. 3)
54	     *   - null      → unlimited (feature included with "Unlimited"/no value)
55	     *   - 0         → no access (feature not included, or user has no plan)
56	     */
57	    public function numericLimit(User $user, string $slug): ?int
58	    {
59	        $feature = $this->features($user)->get($slug);
60	
61	        if (! $feature || ! $feature->pivot->included) {
62	            return 0; // not entitled at all
63	        }
64	
65	        $value = $feature->pivot->value;
66	
67	        if ($value === null || ! is_numeric($value)) {
68	            return null; // included but "Unlimited"
69	        }
70	
71	        return (int) $value;
72	    }
73	}
