3	namespace App\Http\Controllers;
4	
5	use App\Models\MemberSearchCount;
6	use App\Models\SearchHistory;
7	use App\Models\User;
8	use App\Services\PlanEntitlements;
9	use App\Support\Verification\VerificationLevelResolver;
10	use Illuminate\Http\JsonResponse;
11	use Illuminate\Http\Request;
12	use Illuminate\Support\Facades\DB;
13	
14	class MemberController extends Controller
15	{
16	    /**
17	     * Search a member by their SAFEE PIN (safee_id).
18	     * GET /members/search?pin=SMXXXXXXXX
19	     */
20	    public function searchByPin(Request $request): JsonResponse
21	    {
22	        $pin = strtoupper(trim($request->query('pin', '')));
23	
24	        if (strlen($pin) < 4) {
25	            return response()->json([
26	                'success' => false,
27	                'message' => 'PIN too short.',
28	            ], 422);
29	        }
30	
31	        $user = User::where(User::safeeColumn(), $pin)
32	            ->where('status', 'active')
33	            ->first();
34	
35	        if (!$user) {
36	            return response()->json([
37	                'success' => false,
38	                'message' => 'Member not found.',
39	            ], 404);
40	        }
41	
42	        // Do not return own profile
43	        if ($user->id === $request->user()->id) {
44	            return response()->json([
45	                'success' => false,
46	                'message' => 'You cannot search yourself.',
47	            ], 422);
48	        }
49	
50	        // Expired / cancelled trial → search is disabled until they pay.
51	        if (! app(PlanEntitlements::class)->subscriptionActive($request->user())) {
52	            return response()->json([
53	                'success' => false,
54	                'message' => 'Your plan has expired. Subscribe to continue searching members.',
55	                'subscription_required' => true,
56	            ], 403);
57	        }
58	
59	        if ($this->pinSearchLimitReached($request->user())) {
60	            return response()->json([
61	                'success' => false,
62	                'message' => 'You have reached your monthly SAFEE PIN search limit. Upgrade your plan to search more.',
63	                'required_feature' => 'pin_search',
64	            ], 403);
65	        }
66	
67	        $this->logSearch($request, $user, $pin, 'pin');
68	
69	        return response()->json([
70	            'success' => true,
71	            'data'    => $this->formatMember($user),
72	        ]);
73	    }
74	
75	    /**
76	     * Search a member by QR code (also safee_id encoded in QR).
77	     * GET /members/qr?code=SMXXXXXXXX
78	     */
79	    public function searchByQR(Request $request): JsonResponse
80	    {
81	        $code = strtoupper(trim($request->query('code', '')));
82	
83	        if (strlen($code) < 4) {
84	            return response()->json([
85	                'success' => false,
86	                'message' => 'Code too short.',
87	            ], 422);
88	        }
89	
90	        $user = User::where(User::safeeColumn(), $code)
91	            ->where('status', 'active')
92	            ->first();
93	
94	        if (!$user) {
95	            return response()->json([
96	                'success' => false,
97	                'message' => 'Member not found.',
98	            ], 404);
99	        }
100	
101	        if ($user->id === $request->user()->id) {
102	            return response()->json([
103	                'success' => false,
104	                'message' => 'You cannot search yourself.',
105	            ], 422);
106	        }
107	
108	        // Expired / cancelled trial → search is disabled until they pay.
109	        if (! app(PlanEntitlements::class)->subscriptionActive($request->user())) {
110	            return response()->json([
111	                'success' => false,
112	                'message' => 'Your plan has expired. Subscribe to continue searching members.',
113	                'subscription_required' => true,
114	            ], 403);
115	        }
116	
117	        if ($this->pinSearchLimitReached($request->user())) {
118	            return response()->json([
119	                'success' => false,
120	                'message' => 'You have reached your monthly SAFEE PIN search limit. Upgrade your plan to search more.',
121	                'required_feature' => 'pin_search',
122	            ], 403);
123	        }
124	
125	        $this->logSearch($request, $user, $code, 'qr');
126	
127	        return response()->json([
128	            'success' => true,
129	            'data'    => $this->formatMember($user),
130	        ]);
131	    }
132	
133	    /**
134	     * Members the current user has previously searched for (PIN or QR),
135	     * most recent first — lets the app show a "recently searched" list
136	     * that survives reinstalls, since it lives server-side. Backed by
137	     * `member_search_counts`, which holds exactly one (deduped) row per
138	     * searcher-member pair, so this is a plain indexed lookup rather than
139	     * a GROUP BY over the full search log.
140	     * GET /members/recent-searches
141	     */
142	    public function recentSearches(Request $request): JsonResponse
143	    {
144	        $rows = MemberSearchCount::where('searcher_id', $request->user()->id)
145	            ->orderByDesc('last_searched_at')
146	            ->take(20)
147	            ->get();
148	
149	        $usersById = User::whereIn('id', $rows->pluck('member_id'))
150	            ->where('status', 'active')
151	            ->get()
152	            ->keyBy(fn (User $u) => (string) $u->id);
153	
154	        $members = $rows
155	            ->map(fn (MemberSearchCount $row) => $usersById->get((string) $row->member_id))
156	            ->filter()
157	            ->map(fn (User $u) => $this->formatMember($u))
158	            ->values();
159	
160	        return response()->json([
161	            'success' => true,
162	            'data'    => $members,
163	        ]);
164	    }
165	
166	    /**
167	     * Enforces the searcher's plan PIN-search quota, reset per calendar month.
168	     * Every PIN search action counts (including re-searching the same member),
169	     * counted from search_history for the current month. The allowance comes
170	     * from the plan_feature matrix ('pin_search') via PlanEntitlements:
171	     *   - null limit → Unlimited (no enforcement)
172	     *   - 0          → no plan / not entitled (blocked)
173	     */
174	    private function pinSearchLimitReached(User $searcher): bool
175	    {
176	        $limit = app(PlanEntitlements::class)->numericLimit($searcher, 'pin_search');
177	
178	        if ($limit === null) {
179	            return false; // unlimited
180	        }
181	
182	        $usedThisMonth = SearchHistory::where('searcher_id', $searcher->id)
183	            ->whereIn('method', ['pin', 'qr'])
184	            ->where('created_at', '>=', now()->startOfMonth())
185	            ->count();
186	
187	        return $usedThisMonth >= $limit;
188	    }
189	
190	    private function logSearch(Request $request, User $found, string $query, string $method): void
191	    {
192	        $searcherId = $request->user()->id;
193	        $now = now();
194	
195	        SearchHistory::create([
196	            'searcher_id'   => $searcherId,
197	            'found_user_id' => $found->id,
198	            'query'         => $query,
199	            'method'        => $method,
200	        ]);
201	
202	        DB::statement(
203	            'INSERT INTO member_search_counts (searcher_id, member_id, search_count, last_searched_at, created_at, updated_at)
204	             VALUES (?, ?, 1, ?, ?, ?)
205	             ON DUPLICATE KEY UPDATE
206	                 search_count = search_count + 1,
207	                 last_searched_at = VALUES(last_searched_at),
208	                 updated_at = VALUES(updated_at)',
209	            [$searcherId, $found->id, $now, $now, $now],
210	        );
211	    }
212	
213	    private function formatMember(User $user): array
214	    {
215	        return [
216	            'id'                => $user->id,
217	            'name'              => $user->display_name ?? 'SAFEE User',
218	            'safeePIN'          => $user->safee_pin,
219	            'avatarUrl'         => $user->avatar_url,
220	            'trustScore'        => (int) ($user->trust_score ?? 0),
221	            'verificationLevel' => VerificationLevelResolver::fromUser($user->kyc_status, $user->trust_tier),
222	            'subscriptionPlan'  => 'free',
223	            'rating'            => 0.0,
224	            'totalMeetings'     => 0,
225	            'badges'            => [],
226	        ];
227	    }
228	}
