5	use Illuminate\Database\Eloquent\Model;
6	use Illuminate\Database\Eloquent\Relations\BelongsToMany;
7	use Illuminate\Database\Eloquent\Relations\HasMany;
8	
9	class SubscriptionPlan extends Model
10	{
11	    protected $fillable = [
12	        'name', 'slug', 'monthly_price', 'yearly_price', 'trial_days',
13	        'pin_search_limit', 'features', 'icon', 'color', 'sort_order', 'is_active',
14	        'monthly_stripe_price_id', 'yearly_stripe_price_id',
15	    ];
16	
17	    protected function casts(): array
18	    {
19	        return [
20	            'features' => 'array',
21	            'monthly_price' => 'decimal:2',
22	            'yearly_price' => 'decimal:2',
23	            'trial_days' => 'integer',
24	            'pin_search_limit' => 'integer',
25	            'is_active' => 'boolean',
26	        ];
27	    }
28	
29	    public function subscriptions(): HasMany
30	    {
31	        return $this->hasMany(Subscription::class, 'plan_id');
32	    }
33	
34	    // Named comparisonFeatures (not features) to avoid clashing with the
35	    // legacy free-text `features` JSON column still used by the admin CRUD.
36	    public function comparisonFeatures(): BelongsToMany
37	    {
38	        return $this->belongsToMany(Feature::class, 'plan_feature', 'plan_id', 'feature_id')
39	            ->withPivot('included', 'value')
40	            ->withTimestamps();
41	    }
42	
43	    public function scopeActive($query)
44	    {
45	        return $query->where('is_active', true);
46	    }
47	
48	    /** null pin_search_limit means unlimited searches on this plan. */
49	    public function hasUnlimitedPinSearch(): bool
50	    {
51	        return $this->pin_search_limit === null;
52	    }
53	}
