1	<?php
2	
3	namespace App\Services;
4	
5	use App\Models\Subscription;
6	use App\Models\SubscriptionPlan;
7	use App\Models\User;
8	
9	class SubscriptionService
10	{
11	    /**
12	     * Puts a freshly-registered user onto the free-trial plan: creates a trial
13	     * subscription lasting the plan's trial_days (default 100) and points the
14	     * user at it. Idempotent — skips if the user already has any subscription,
15	     * and no-ops safely if the free_trial plan hasn't been seeded yet.
16	     *
17	     * When the trial ends it is expired (not auto-charged) by
18	     * ProcessSubscriptionTrials; the user must then pay to keep searching/chatting.
19	     */
20	    public function startFreeTrial(User $user): void
21	    {
22	        $plan = SubscriptionPlan::where('slug', 'free_trial')->first();
23	
24	        if (! $plan || $user->subscriptions()->exists()) {
25	            return;
26	        }
27	
28	        $trialDays = (int) ($plan->trial_days ?: 100);
29	
30	        Subscription::create([
31	            'user_id' => $user->id,
32	            'plan_id' => $plan->id,
33	            'price' => $plan->monthly_price,
34	            'billing_cycle' => 'monthly',
35	            'status' => 'trial',
36	            'trial_days' => $trialDays,
37	            'started_at' => now(),
38	            'renews_at' => now()->addDays($trialDays),
39	        ]);
40	
41	        // saveQuietly: we're already inside the user's created event; avoid
42	        // firing further model events for this housekeeping update.
43	        $user->plan_id = $plan->id;
44	        $user->subscription_status = 'trial';
45	        $user->saveQuietly();
46	    }
47	}
