15	class SubscriptionController extends Controller
16	{
17	    public function __construct(private readonly StripeService $stripe)
18	    {
19	    }
20	
21	    /**
22	     * GET /api/subscriptions/plans — "Plans" screen.
23	     * Everything is catalog-driven from subscription_plans.
24	     */
25	    public function plans(): JsonResponse
26	    {
27	        return response()->json(
28	            SubscriptionPlan::active()->orderBy('sort_order')->get()
29	        );
30	    }
31	
32	    /**
33	     * GET /api/subscriptions/comparison — feature comparison matrix.
34	     * Returns active plans (columns) and features grouped into sections (rows),
35	     * each row carrying every plan's included/value so the client can render a
36	     * complete grid without extra lookups. Missing = not included.
37	     */
38	    public function comparison(): JsonResponse
39	    {
40	        $plans = SubscriptionPlan::active()
41	            ->orderBy('sort_order')
42	            ->get(['id', 'slug', 'name', 'monthly_price', 'yearly_price', 'trial_days']);
43	
44	        // Baseline cell for every plan, overridden where a mapping exists.
45	        $baseline = $plans->mapWithKeys(fn ($plan) => [
46	            $plan->slug => ['included' => false, 'value' => null],
47	        ])->all();
48	
49	        $features = Feature::active()
50	            ->orderBy('sort_order')
51	            ->with(['plans:id,slug'])
52	            ->get();
53	
54	        $groups = $features
55	            ->groupBy('group')
56	            ->map(fn ($groupFeatures, $groupName) => [
57	                'name' => $groupName,
58	                'features' => $groupFeatures->map(function (Feature $feature) use ($baseline) {
59	                    $cells = $baseline;
60	                    foreach ($feature->plans as $plan) {
61	                        $cells[$plan->slug] = [
62	                            'included' => (bool) $plan->pivot->included,
63	                            'value' => $plan->pivot->value,
64	                        ];
65	                    }
66	
67	                    return [
68	                        'slug' => $feature->slug,
69	                        'name' => $feature->name,
70	                        'type' => $feature->type,
71	                        'plans' => $cells,
72	                    ];
73	                })->values(),
74	            ])
75	            ->values();
76	
77	        return response()->json([
78	            'plans' => $plans,
79	            'groups' => $groups,
80	        ]);
81	    }
