83	    /**
84	     * GET /api/subscriptions/current — Profile "Current Plan" card.
85	     */
86	    public function current(Request $request): JsonResponse
87	    {
88	        $subscription = $request->user()->activeSubscription()->with('plan')->first();
89	
90	        if (! $subscription) {
91	            return response()->json(['message' => 'No active subscription'], 404);
92	        }
93	
94	        return response()->json($subscription);
95	    }
