97	    /**
98	     * POST /api/subscriptions/subscribe — pick a plan (by slug).
99	     * Price / trial length come from the catalog row, never hardcoded.
100	     * Free-trial plans stay local-only (no card needed); paid plans create a
101	     * real Stripe subscription and may come back needing 3DS confirmation.
102	     */
103	    public function subscribe(Request $request): JsonResponse
104	    {
105	        $validated = $request->validate([
106	            'plan_slug' => ['required', 'string', Rule::exists('subscription_plans', 'slug')->where('is_active', true)],
107	            'billing_cycle' => ['required', Rule::in(['monthly', 'yearly'])],
108	            'stripe_payment_method_id' => ['nullable', 'string'],
109	        ]);
110	
111	        $user = $request->user();
112	        $plan = SubscriptionPlan::where('slug', $validated['plan_slug'])->firstOrFail();
113	
114	        $isTrial = (int) $plan->trial_days > 0;
115	        $price = $validated['billing_cycle'] === 'yearly' ? $plan->yearly_price : $plan->monthly_price;
116	
117	        // A paid plan needs a payment method up front; a plan starting with a
118	        // free trial does not.
119	        if (! $isTrial && (float) $price > 0 && empty($validated['stripe_payment_method_id'])) {
120	            return response()->json([
121	                'message' => 'A payment method is required for this plan.',
122	            ], 422);
123	        }
124	
125	        $needsStripe = ! $isTrial && (float) $price > 0;
126	        $stripeCustomer = null;
127	        $stripeSubscription = null;
128	
129	        if ($needsStripe) {
130	            $priceId = $this->stripe->resolvePriceId($plan, $validated['billing_cycle']);
131	
132	            if (! $priceId) {
133	                return response()->json([
134	                    'message' => "Plan '{$plan->slug}' has no Stripe price configured for {$validated['billing_cycle']} billing.",
135	                ], 422);
136	            }
137	
138	            $stripeCustomer = $this->stripe->createOrGetCustomer($user);
139	            $stripeSubscription = $this->stripe->createSubscription(
140	                $stripeCustomer,
141	                $priceId,
142	                $validated['stripe_payment_method_id'],
143	                null,
144	            );
145	        }
146	
147	        $subscription = DB::transaction(function () use ($user, $plan, $validated, $isTrial, $price, $stripeCustomer, $stripeSubscription) {
148	            // A freshly created Stripe subscription is 'incomplete' until its
149	            // first invoice is paid — only 'active'/'trialing' from Stripe
150	            // may grant entitlements; everything else must stay non-active
151	            // here too, or scopeActive() would let an unpaid user in.
152	            $status = match (true) {
153	                $isTrial => 'trial',
154	                $stripeSubscription?->status === 'active' => 'active',
155	                default => 'incomplete',
156	            };
157	
158	            $subscription = Subscription::create([
159	                'user_id' => $user->id,
160	                'plan_id' => $plan->id,
161	                'price' => $price,
162	                'billing_cycle' => $validated['billing_cycle'],
163	                'status' => $status,
164	                'trial_days' => $plan->trial_days,
165	                'started_at' => now(),
166	                'renews_at' => match (true) {
167	                    $isTrial => now()->addDays($plan->trial_days),
168	                    $validated['billing_cycle'] === 'yearly' => now()->addYear(),
169	                    default => now()->addMonth(),
170	                },
171	                'stripe_customer_id' => $stripeCustomer?->id,
172	                'stripe_subscription_id' => $stripeSubscription?->id,
173	            ]);
174	
175	            $user->update([
176	                'plan_id' => $plan->id,
177	                'subscription_status' => $subscription->status,
178	            ]);
179	
180	            return $subscription;
181	        });
182	
183	        $response = $subscription->load('plan')->toArray();
184	
185	        // App must confirm this client_secret via Stripe SDK (confirmPayment)
186	        // before the subscription becomes chargeable; the webhook then flips
187	        // the local status to 'active' once invoice.paid fires.
188	        $confirmationSecret = $stripeSubscription?->latest_invoice?->confirmation_secret;
189	        if ($confirmationSecret) {
190	            $response['payment_intent_client_secret'] = $confirmationSecret->client_secret;
191	            $response['payment_intent_status'] = $stripeSubscription->status;
192	        }
193	
194	        return response()->json($response, 201);
195	    }
