199	     */
200	    public function cancel(Request $request): JsonResponse
201	    {
202	        $user = $request->user();
203	        $subscription = $user->activeSubscription;
204	
205	        if (! $subscription) {
206	            return response()->json(['message' => 'No active subscription'], 404);
207	        }
208	
209	        if ($subscription->stripe_subscription_id) {
210	            $this->stripe->cancelSubscription($subscription->stripe_subscription_id);
211	        }
212	
213	        DB::transaction(function () use ($user, $subscription) {
214	            $subscription->update(['status' => 'cancelled', 'cancelled_at' => now()]);
215	            $user->update(['subscription_status' => 'cancelled']);
216	        });
217	
218	        return response()->json(['message' => 'Subscription cancelled']);
219	    }
220	}
