2	
3	namespace App\Http\Controllers\Api;
4	
5	use App\Http\Controllers\Controller;
6	use App\Models\Payment;
7	use App\Models\PaymentWebhookEvent;
8	use App\Models\Subscription;
9	use Illuminate\Http\JsonResponse;
10	use Illuminate\Http\Request;
11	use Illuminate\Support\Facades\DB;
12	use Illuminate\Support\Facades\Log;
13	use Stripe\Exception\SignatureVerificationException;
14	use UnexpectedValueException;
15	
16	class StripeWebhookController extends Controller
17	{
18	    /**
19	     * POST /api/v1/webhooks/stripe — no auth middleware, Stripe calls this
20	     * directly. Trust boundary is the signature check below, not sanctum.
21	     *
22	     * Renewals, failed charges, and out-of-band cancellations (e.g. from the
23	     * Stripe dashboard) all arrive here rather than through an app screen, so
24	     * this is the only reliable place to keep `subscriptions`/`users` in sync.
25	     */
26	    public function __invoke(Request $request): JsonResponse
27	    {
28	        try {
29	            $event = app(\App\Services\StripeService::class)->verifyWebhookSignature(
30	                $request->getContent(),
31	                $request->header('Stripe-Signature', ''),
32	            );
33	        } catch (UnexpectedValueException|SignatureVerificationException $e) {
34	            Log::warning('Stripe webhook signature verification failed', ['error' => $e->getMessage()]);
35	
36	            return response()->json(['message' => 'Invalid signature'], 400);
37	        }
38	
39	        // Idempotency: Stripe retries undelivered webhooks, so a repeat event
40	        // id must be a no-op rather than double-crediting/cancelling.
41	        $alreadyProcessed = PaymentWebhookEvent::where('stripe_event_id', $event->id)
42	            ->whereNotNull('processed_at')
43	            ->exists();
44	
45	        if ($alreadyProcessed) {
46	            return response()->json(['message' => 'Already processed']);
47	        }
48	
49	        $record = PaymentWebhookEvent::firstOrCreate(
50	            ['stripe_event_id' => $event->id],
51	            ['type' => $event->type, 'payload' => $event->toArray()],
52	        );
53	
54	        DB::transaction(function () use ($event) {
55	            match ($event->type) {
56	                'invoice.paid' => $this->handleInvoicePaid($event),
57	                'invoice.payment_failed' => $this->handlePaymentFailed($event),
58	                'customer.subscription.deleted' => $this->handleSubscriptionDeleted($event),
59	                default => null,
60	            };
61	        });
62	
63	        $record->update(['processed_at' => now()]);
64	
65	        return response()->json(['message' => 'ok']);
66	    }
67	
68	    /**
69	     * Stripe's newer API versions moved the subscription id off the invoice's
70	     * top-level `subscription` field (removed) onto
71	     * `parent.subscription_details.subscription`.
72	     */
73	    private function invoiceSubscriptionId($invoice): ?string
74	    {
75	        return $invoice->parent?->subscription_details?->subscription ?? $invoice->subscription ?? null;
76	    }
77	
78	    private function handleInvoicePaid($event): void
79	    {
80	        $invoice = $event->data->object;
81	        $subscription = Subscription::where('stripe_subscription_id', $this->invoiceSubscriptionId($invoice))->first();
82	
83	        if (! $subscription) {
84	            return;
85	        }
86	
87	        $subscription->update([
88	            'status' => 'active',
89	            'renews_at' => $subscription->billing_cycle === 'yearly' ? now()->addYear() : now()->addMonth(),
90	        ]);
91	        $subscription->user()->update(['subscription_status' => 'active']);
92	
93	        Payment::updateOrCreate(
94	            ['stripe_invoice_id' => $invoice->id],
95	            [
96	                'user_id' => $subscription->user_id,
97	                'subscription_id' => $subscription->id,
98	                'stripe_payment_intent_id' => $invoice->payment_intent,
99	                'amount' => $invoice->amount_paid,
100	                'currency' => $invoice->currency,
101	                'status' => 'succeeded',
102	                'paid_at' => now(),
103	            ],
104	        );
105	    }
106	
107	    private function handlePaymentFailed($event): void
108	    {
109	        $invoice = $event->data->object;
110	        $subscription = Subscription::where('stripe_subscription_id', $this->invoiceSubscriptionId($invoice))->first();
111	
112	        if (! $subscription) {
113	            return;
114	        }
115	
116	        $subscription->update(['status' => 'expired']);
117	        $subscription->user()->update(['subscription_status' => 'expired']);
118	
119	        Payment::updateOrCreate(
120	            ['stripe_invoice_id' => $invoice->id],
121	            [
122	                'user_id' => $subscription->user_id,
123	                'subscription_id' => $subscription->id,
124	                'stripe_payment_intent_id' => $invoice->payment_intent,
125	                'amount' => $invoice->amount_due,
126	                'currency' => $invoice->currency,
127	                'status' => 'failed',
128	            ],
129	        );
130	    }
131	
132	    private function handleSubscriptionDeleted($event): void
133	    {
134	        $stripeSubscription = $event->data->object;
135	        $subscription = Subscription::where('stripe_subscription_id', $stripeSubscription->id)->first();
136	
137	        if (! $subscription) {
138	            return;
139	        }
140	
141	        $subscription->update(['status' => 'cancelled', 'cancelled_at' => now()]);
142	        $subscription->user()->update(['subscription_status' => 'cancelled']);
143	    }
144	}
