3	namespace App\Services;
4	
5	use App\Models\SubscriptionPlan;
6	use App\Models\User;
7	use Stripe\Customer;
8	use Stripe\StripeClient;
9	use Stripe\Subscription as StripeSubscription;
10	
11	class StripeService
12	{
13	    private StripeClient $client;
14	
15	    public function __construct()
16	    {
17	        $this->client = new StripeClient(config('services.stripe.secret'));
18	    }
19	
20	    /**
21	     * Reuses the user's existing Stripe customer, or creates one and stores
22	     * its id — every subscription/payment call needs this as the anchor.
23	     */
24	    public function createOrGetCustomer(User $user): Customer
25	    {
26	        $existingId = $user->activeSubscription?->stripe_customer_id;
27	
28	        if ($existingId) {
29	            return $this->client->customers->retrieve($existingId);
30	        }
31	
32	        return $this->client->customers->create([
33	            'email' => $user->email,
34	            'name' => $user->displayName ?? $user->safeeId,
35	            'metadata' => ['user_id' => $user->id],
36	        ]);
37	    }
38	
39	    /**
40	     * Creates the recurring Stripe subscription for a paid (or trialing)
41	     * plan. $priceId must be the Stripe Price id configured against the
42	     * plan's slug (monthly_stripe_price_id / yearly_stripe_price_id).
43	     */
44	    public function createSubscription(
45	        Customer $customer,
46	        string $priceId,
47	        ?string $paymentMethodId,
48	        ?int $trialDays
49	    ): StripeSubscription {
50	        if ($paymentMethodId) {
51	            // Stripe test tokens (e.g. pm_card_visa) alias to a different,
52	            // real PaymentMethod id once attached — always use the id Stripe
53	            // hands back, not the id we were given.
54	            $attached = $this->client->paymentMethods->attach($paymentMethodId, ['customer' => $customer->id]);
55	            $this->client->customers->update($customer->id, [
56	                'invoice_settings' => ['default_payment_method' => $attached->id],
57	            ]);
58	        }
59	
60	        $params = [
61	            'customer' => $customer->id,
62	            'items' => [['price' => $priceId]],
63	            'payment_behavior' => 'default_incomplete',
64	            // Stripe's newer API versions moved the client secret needed for
65	            // 3DS/off-session confirmation off `latest_invoice.payment_intent`
66	            // (removed) onto `latest_invoice.confirmation_secret`.
67	            'expand' => ['latest_invoice.confirmation_secret'],
68	        ];
69	
70	        if ($trialDays) {
71	            $params['trial_period_days'] = $trialDays;
72	        }
73	
74	        return $this->client->subscriptions->create($params);
75	    }
76	
77	    public function cancelSubscription(string $stripeSubscriptionId): StripeSubscription
78	    {
79	        return $this->client->subscriptions->cancel($stripeSubscriptionId);
80	    }
81	
82	    public function resolvePriceId(SubscriptionPlan $plan, string $billingCycle): ?string
83	    {
84	        return $billingCycle === 'yearly' ? $plan->yearly_stripe_price_id : $plan->monthly_stripe_price_id;
85	    }
86	
87	    public function verifyWebhookSignature(string $payload, string $signatureHeader): \Stripe\Event
88	    {
89	        return \Stripe\Webhook::constructEvent(
90	            $payload,
91	            $signatureHeader,
92	            config('services.stripe.webhook_secret')
93	        );
94	    }
95	}
