<?php
use App\Models\Subscription;
use App\Models\User;

$stripe = new \Stripe\StripeClient(env('STRIPE_SECRET'));

$userIds = [4, 24, 26];

foreach ($userIds as $uid) {
    echo "=== user $uid ===\n";
    $subs = Subscription::where('user_id', $uid)
        ->whereNotNull('stripe_subscription_id')
        ->orderByDesc('created_at')
        ->get();

    $confirmedActive = [];

    foreach ($subs as $sub) {
        try {
            $remote = $stripe->subscriptions->retrieve($sub->stripe_subscription_id);
        } catch (\Throwable $e) {
            echo "  sub {$sub->id} ({$sub->stripe_subscription_id}) -> STRIPE ERROR: {$e->getMessage()}\n";
            continue;
        }

        echo "  sub {$sub->id} plan_id={$sub->plan_id} local_status={$sub->status} stripe_status={$remote->status} created={$sub->created_at}\n";

        $mapped = match ($remote->status) {
            'active', 'trialing' => 'active',
            'canceled' => 'cancelled',
            'incomplete_expired' => 'expired',
            'past_due', 'unpaid' => 'expired',
            default => null,
        };

        if ($mapped && $mapped !== $sub->status) {
            $sub->update(['status' => $mapped]);
            echo "    -> updated local status to '$mapped'\n";
        }

        if ($remote->status === 'active') {
            $confirmedActive[] = $sub->fresh();
        }
    }

    if (count($confirmedActive) === 0) {
        echo "  no confirmed-active Stripe subscription found for this user; leaving user record untouched.\n";
        continue;
    }

    // Canonical = most recent confirmed-active subscription.
    $canonical = collect($confirmedActive)->sortByDesc('created_at')->first();

    $user = User::find($uid);
    $before = ['plan_id' => $user->plan_id, 'subscription_status' => $user->subscription_status];
    $user->update(['plan_id' => $canonical->plan_id, 'subscription_status' => 'active']);
    echo "  user updated: plan_id {$before['plan_id']} -> {$canonical->plan_id}, subscription_status {$before['subscription_status']} -> active (canonical sub {$canonical->id})\n";

    if (count($confirmedActive) > 1) {
        $dupIds = collect($confirmedActive)->pluck('id')->diff([$canonical->id])->values();
        echo "  *** WARNING: " . count($confirmedActive) . " Stripe subscriptions are simultaneously active for this user (ids: " . collect($confirmedActive)->pluck('id')->implode(',') . "). Only sub {$canonical->id} was set as canonical; the others (" . $dupIds->implode(',') . ") are still live/billing on Stripe and were NOT cancelled. ***\n";
    }
}
EOF
